import sys
sys.setrecursionlimit(10000)

def get_total_number_of_sequences(m, n):
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, prev):
        if pos == n:
            return 1
        total = 0
        next_val = 2 * prev
        while next_val <= m:
            total += dp(pos + 1, next_val)
            next_val += 1
        return total

    result = 0
    for start in range(1, m + 1):
        result += dp(1, start)
    return result
